\begin{card}
\begin{html}{Problema de la Colina (Trigonometría)}
<div style="position: relative; width: 700px; height: 400px; margin: 0 auto;">
  <!-- 1. Lienzo Canvas 2D -->
  <canvas id="lienzoGeo" width="700" height="400" style="border: 1px solid #e0e0e0; background-color: #ffffff; border-radius: 8px;"></canvas>

  <!-- 2. Etiquetas KaTeX Flotantes (Posicionadas exactamente sobre el gráfico) -->
  <div id="lbl-piedra" style="position: absolute; top: 310px; left: 70px; pointer-events: none;"></div>
  <div id="lbl-base"   style="position: absolute; top: 310px; left: 280px; pointer-events: none;"></div>
  <div id="lbl-inicio" style="position: absolute; top: 50px;  left: 550px; pointer-events: none;"></div>
  <div id="lbl-mitad"  style="position: absolute; top: 180px; left: 420px; pointer-events: none;"></div>

  <div id="lbl-alpha"  style="position: absolute; top: 265px; left: 340px; pointer-events: none;"></div>
  <div id="lbl-beta"   style="position: absolute; top: 55px;  left: 470px; pointer-events: none;"></div>
  <div id="lbl-gamma"  style="position: absolute; top: 175px; left: 345px; pointer-events: none;"></div>
</div>

<script>
  function iniciarGrafico() {
    // Si KaTeX no ha cargado aún desde la red, reintentar en 100ms
    if (window.katex) {
      katex.render("\\text{Piedra}", document.getElementById('lbl-piedra'));
      katex.render("\\text{Base}", document.getElementById('lbl-base'));
      katex.render("\\text{Inicio}", document.getElementById('lbl-inicio'));
      katex.render("\\text{Mitad}", document.getElementById('lbl-mitad'));

      katex.render("\\alpha", document.getElementById('lbl-alpha'));
      katex.render("\\beta", document.getElementById('lbl-beta'));
      katex.render("\\gamma", document.getElementById('lbl-gamma'));
    } else {
      setTimeout(iniciarGrafico, 100);
      return;
    }

    dibujarDiagrama();
  }

  function dibujarDiagrama() {
    const canvas = document.getElementById('lienzoGeo');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const escala = 65; 

    const anguloColina = 45 * (Math.PI / 180); 
    const longitudColina = 5.5; 

    const nivelSueloY = 300;
    const S = { x: 100, y: nivelSueloY }; 
    const B = { x: S.x + (3 * escala), y: nivelSueloY }; 

    const C = { 
      x: B.x + (longitudColina * escala * Math.cos(anguloColina)), 
      y: B.y - (longitudColina * escala * Math.sin(anguloColina)) 
    };
    const M = { 
      x: B.x + ((longitudColina/2) * escala * Math.cos(anguloColina)), 
      y: B.y - ((longitudColina/2) * escala * Math.sin(anguloColina)) 
    };

    ctx.strokeStyle = "#2c3e50";
    ctx.lineWidth = 2;

    // --- Suelo y Colina ---
    ctx.beginPath();
    ctx.moveTo(30, nivelSueloY); 
    ctx.lineTo(670, nivelSueloY); 

    ctx.moveTo(B.x, B.y);
    ctx.lineTo(C.x, C.y); 
    ctx.stroke();

    // --- Líneas Punteadas ---
    ctx.beginPath();
    ctx.setLineDash([6, 4]); 
    ctx.lineWidth = 1.2;

    ctx.moveTo(C.x, C.y); ctx.lineTo(S.x, S.y);
    ctx.moveTo(M.x, M.y); ctx.lineTo(S.x, S.y);

    ctx.moveTo(C.x, C.y); ctx.lineTo(C.x - 120, C.y);
    ctx.moveTo(M.x, M.y); ctx.lineTo(M.x - 120, M.y);
    ctx.stroke();

    ctx.setLineDash([]); 

    // --- Arcos de los Ángulos ---
    ctx.beginPath();
    ctx.lineWidth = 1.5;

    const anguloLineaColina = Math.atan2(C.y - B.y, C.x - B.x);
    ctx.arc(B.x, B.y, 45, 0, anguloLineaColina, true);
    ctx.stroke();

    const anguloVisionC = Math.atan2(S.y - C.y, S.x - C.x);
    ctx.beginPath();
    ctx.arc(C.x, C.y, 50, Math.PI, anguloVisionC, true);
    ctx.stroke();

    const anguloVisionM = Math.atan2(S.y - M.y, S.x - M.x);
    ctx.beginPath();
    ctx.arc(M.x, M.y, 55, Math.PI, anguloVisionM, true);
    ctx.stroke();

    // --- Puntos Rojos ---
    ctx.fillStyle = "##1e293b"; 
    const puntos = [S, B, C, M];
    puntos.forEach(pt => {
      ctx.beginPath();
      ctx.arc(pt.x, pt.y, 4.5, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  // Iniciar la secuencia de renderizado
  iniciarGrafico();
</script>
\end{html}
\end{card}
