            ctx.lineTo(canvas.width, origenY);
            // Eje Y
            ctx.moveTo(origenX, 0); 
            ctx.lineTo(origenX, canvas.height);
            ctx.stroke();

            // C. Dibujar la curva matemática animada
            ctx.beginPath();
            ctx.strokeStyle = "#f38ba8"; // Color rosa neón
            ctx.lineWidth = 3;

            for (let px = 0; px <= (canvas.width - origenX); px++) {
                let x = px / escalaX;
                let y = Math.sin(2 * x - t);
                let py = origenY - (y * escalaY);

                if (px === 0) {
                    ctx.moveTo(origenX + px, py);
                } else {
                    ctx.lineTo(origenX + px, py);
                }
            }
            ctx.stroke();

            // D. Actualizar la etiqueta de tiempo en vivo con KaTeX
            if (window.katex) {
                katex.render(`t = ${t.toFixed(2)} \\text{ s}`, elemTiempo);
            }

            // E. Incrementar el tiempo para la onda
            t += 0.04;

            // F. Siguiente fotograma de animación
            requestAnimationFrame(animar);
        }

        animar();
    }

    iniciarAnimacion();
</script>
\end{html}
\end{card}

chapters.teoria:
\begin{definicion}{Región Acotada}
Para medir una superficie delimitada por múltiples fronteras dinámicas, debemos identificar las funciones que actúan como límite superior e inferior. Si $f$ y $g$ son funciones continuas en un intervalo cerrado $[a, b]$, y se cumple que $f(x) \ge g(x)$ para todo $x$ en dicho intervalo, definimos analíticamente a $f(x)$ como la curva "techo" y a $g(x)$ como la curva "piso".
\end{definicion}

\begin{teorema}{Área entre Dos Curvas}
Si una región bidimensional está acotada superiormente por la gráfica de $y = f(x)$, inferiormente por $y = g(x)$, y en los laterales por las rectas verticales $x = a$ y $x = b$, entonces su área exacta $A$ se calcula mediante la integral definida de la diferencia de ambas funciones:
    $$ A = \displaystyle\int_a^b [f(x) - g(x)] \, dx $$
\end{teorema}

\begin{metodo}{Área entre curvas}   
\problema{Calcular el área de la región acotada por las curvas $f(x) = x^3$ y $g(x) = x$.}

\paso{1}{Igualación y Resolución} 
Para determinar los límites de integración, debemos establecer los puntos exactos donde las gráficas de las funciones se intersectan. Igualamos ambas funciones algebraicamente $f(x) = g(x)$ y encontramos todas sus raíces reales. Estas raíces dividirán el área total en subintervalos.
\ejemplo{
Igualamos: $x^3 = x$ es decir $x^3 - x = x(x - 1)(x + 1) = 0$.

Los puntos de intersección son $x = -1$, $x = 0$ y $x = 1$. 

Esto genera dos subintervalos de análisis: $[-1, 0]$ y $[0, 1]$.
}


    \paso{2}{Análisis de Dominancia (Techo y Piso)} 
    En cada subintervalo $[x_i, x_{i+1}]$, seleccionamos un valor de prueba arbitrario (un punto interior) y lo evaluamos en ambas funciones. La función que arroje el valor numérico mayor será la curva "techo" y la menor será la curva "piso" exclusivamente para ese tramo.
    \ejemplo{
    \textbf{Para el tramo} $[-1, 0]$. Probamos con $x = -1/2$. 
    $f(-1/2) = -1/8$ y $g(-1/2) = -1/2$. Como $-1/8 > -1/2$, en este tramo la curva $f(x)$ es el \textbf{techo}.

    \textbf{Para el tramo} $[0, 1]$. Probamos con $x = 1/2$. 
    $f(1/2) = 1/8$ y $g(1/2) = 1/2$. Como $1/2 > 1/8$, en este tramo los roles se invierten y $g(x)$ es el \textbf{techo}.}

    \paso{3}{Planteamiento y Cálculo de la Integral} 
    Se plantea una integral definida independiente por cada subintervalo, utilizando siempre la estructura $\displaystyle\int (\text{techo} - \text{piso}) \, dx$. El área total exacta será la suma geométrica de los resultados de todas estas integrales parciales.
    \ejemplo{
    Planteamos el área total $A$ separando los tramos:
    $$ A= \displaystyle\int_{-1}^0 \left[x^3 - x\right]dx + \displaystyle\int_0^1 \left[x - x^3\right]dx $$
    Calculamos la primera integral:
    $$ \displaystyle\int_{-1}^0 \left[x^3 - x\right]dx= \displaystyle\frac{1}{4}$$
    Calculamos la segunda integral:
    $$ \displaystyle\int_0^1 \left[x - x^3\right]dx = \displaystyle\frac{1}{4} $$
    Área total: $A = \displaystyle\frac{1}{4} + \displaystyle\frac{1}{4} = \displaystyle\frac{1}{2}$
    }

  \end{metodo}


\begin{html}{Gráfico Interactivo: Intersección de Curvas $f(x)=x^3$ y $g(x)=x$}
