  (function() {
    function initCanvas() {
      const canvas = document.getElementById('canvasPaso1');
      if (!canvas) return setTimeout(initCanvas, 50);
      const ctx = canvas.getContext('2d');
      const width = canvas.width, height = canvas.height;
      const scale = 90, cx = width / 2, cy = height / 2;

      const mapX = x => cx + x * scale;
      const mapY = y => cy - y * scale;
      const f = x => Math.pow(x, 3);
      const g = x => x;

      ctx.clearRect(0, 0, width, height);

      // 1. Cuadrícula secundaria
      ctx.beginPath();
      ctx.strokeStyle = '#f1f5f9';
      ctx.lineWidth = 1;
      for (let i = -2; i <= 2; i += 0.5) {
        ctx.moveTo(mapX(i), 0); ctx.lineTo(mapX(i), height);
        ctx.moveTo(0, mapY(i)); ctx.lineTo(width, mapY(i));
      }
      ctx.stroke();

      // 2. Ejes Cartesianos X e Y
      ctx.beginPath();
      ctx.strokeStyle = '#64748b';
      ctx.lineWidth = 1.5;
      ctx.moveTo(0, cy); ctx.lineTo(width, cy);
      ctx.moveTo(cx, 0); ctx.lineTo(cx, height);
      ctx.stroke();

      // 3. Función f(x) = x^3 (Azul)
      ctx.beginPath();
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2.5;
      for (let x = -1.5; x <= 1.5; x += 0.02) {
        if (x === -1.5) ctx.moveTo(mapX(x), mapY(f(x)));
        else ctx.lineTo(mapX(x), mapY(f(x)));
      }
      ctx.stroke();

      // 4. Función g(x) = x (Rojo)
      ctx.beginPath();
      ctx.strokeStyle = '#ef4444';
      ctx.lineWidth = 2.5;
      for (let x = -1.5; x <= 1.5; x += 0.05) {
        if (x === -1.5) ctx.moveTo(mapX(x), mapY(g(x)));
        else ctx.lineTo(mapX(x), mapY(g(x)));
      }
      ctx.stroke();

      // 5. Puntos de Intersección (Verde Esmeralda)
      const drawPoint = (x, y) => {
        ctx.beginPath();
        ctx.arc(mapX(x), mapY(y), 5.5, 0, 2 * Math.PI);
        ctx.fillStyle = '#10b981';
        ctx.fill();
        ctx.strokeStyle = '#0f766e';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      };

      drawPoint(-1, -1);
      drawPoint(0, 0);
      drawPoint(1, 1);
    }

    initCanvas();
  })();
</script>
